INSERT INTO `tag` (`name`, `status`) SELECT 'Hydroponics', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Hydroponics') x);
